<template>
  <div class="learner-dashboard">
    <div class="dashboard-heading"><div><span class="eyebrow">YOUR LEARNING SPACE</span><h1>Good to see you, {{ firstName }}.</h1><p>One small step is still a step forward.</p></div><RouterLink class="browse-link" to="/catalogue">Browse courses <span aria-hidden="true">↗</span></RouterLink></div>
    <section class="stats-row" aria-label="Learning summary"><div v-for="stat in dashboardStats" :key="stat.label" class="stat-card"><span class="stat-label">{{ stat.label }}</span><strong>{{ stat.value }}</strong><span class="stat-detail">{{ stat.detail }}</span></div></section>
    <section v-if="loading" class="dashboard-loading" aria-label="Loading your courses"><v-skeleton-loader type="article" class="skeleton-card large" /><v-skeleton-loader type="list-item" class="skeleton-card" /><v-skeleton-loader type="list-item" class="skeleton-card" /></section>
    <section v-else-if="enrolledCourses.length === 0" class="empty-state-card dashboard-empty"><span class="empty-symbol" aria-hidden="true">✳</span><span class="eyebrow">A FRESH PAGE</span><h2>Make your first move.</h2><p>Your learning space is ready when you are. Find a course that fits where you want to go next.</p><RouterLink class="button-primary" to="/catalogue">Explore the course catalogue <span aria-hidden="true">↗</span></RouterLink></section>
    <template v-else>
      <section class="resume-section"><div class="section-kicker"><span class="focus-dot" /> YOUR NEXT STEP</div><article class="resume-hero-panel"><div class="resume-main"><div class="course-category">{{ primaryCourse.cours.categorie || 'YOUR LEARNING PATH' }}</div><h2>{{ primaryCourse.cours.titre }}</h2><div class="instructor-line"><span class="instructor-avatar" aria-hidden="true">{{ (primaryCourse.cours.formateur?.name || 'E').slice(0, 1) }}</span><span>With {{ primaryCourse.cours.formateur?.name || 'your instructor' }}</span></div><RouterLink class="resume-button" :to="`/cours/${primaryCourse.cours.id}/apprendre`">{{ primaryCourse.inscription.pourcentageProgression === 100 ? 'Review this course' : 'Continue learning' }} <span aria-hidden="true">→</span></RouterLink></div><div class="resume-progress"><div class="progress-top"><div><span class="stat-label">YOUR PROGRESS</span><strong>{{ Math.round(primaryCourse.inscription.pourcentageProgression) }}<small>%</small></strong></div><span class="progress-note">{{ primaryCourse.inscription.pourcentageProgression === 100 ? 'Course complete' : 'Steady progress' }}</span></div><div class="progress-track"><span :style="{ width: `${Math.min(100, Math.max(0, primaryCourse.inscription.pourcentageProgression))}%` }" /></div><div class="progress-foot"><span>{{ primaryCourse.inscription.pourcentageProgression === 100 ? 'Certificate ready to view' : 'Next lesson is ready when you are' }}</span><span aria-hidden="true">↗</span></div></div></article></section>
      <section v-if="secondaryCourses.length" class="other-courses"><div class="section-heading"><div><span class="eyebrow">KEEP YOUR MOMENTUM</span><h2>Your other courses</h2></div><span class="section-count">{{ secondaryCourses.length }} paths</span></div><div class="other-course-list"><article v-for="item in secondaryCourses" :key="item.cours.id" class="other-course"><div class="other-course-mark">{{ getCategoryIcon(item.cours.categorie) }}</div><div class="other-course-copy"><span class="course-category">{{ item.cours.categorie || 'LEARNING PATH' }}</span><h3>{{ item.cours.titre }}</h3><span class="other-progress">{{ Math.round(item.inscription.pourcentageProgression) }}% complete</span></div><div class="other-progress-track"><span :style="{ width: `${Math.min(100, Math.max(0, item.inscription.pourcentageProgression))}%` }" /></div><RouterLink :to="`/cours/${item.cours.id}/apprendre`" class="other-arrow" :aria-label="`Continue ${item.cours.titre}`"><span aria-hidden="true">→</span></RouterLink></article></div></section>
    </template>
  </div>
</template>

<script setup>
import { ref, computed, onMounted } from 'vue';
import { useAuthStore } from '../stores/auth';
import api from '../axios';
import { showErrorToast } from '../composables/useToast.js';
import { useViewLoadState } from '../composables/useViewLoadState.js';

const authStore = useAuthStore();
const { isLoading: loading, markLoading, markLoaded } = useViewLoadState();
const enrolledCourses = ref([]);
const firstName = computed(() => (authStore.user?.name || 'there').split(' ')[0]);
const primaryCourse = computed(() => enrolledCourses.value.find(course => course.inscription.pourcentageProgression > 0 && course.inscription.pourcentageProgression < 100) || enrolledCourses.value[0] || null);
const secondaryCourses = computed(() => primaryCourse.value ? enrolledCourses.value.filter(course => course.cours.id !== primaryCourse.value.cours.id) : []);
const dashboardStats = computed(() => {
  const total = enrolledCourses.value.length;
  const inProgress = enrolledCourses.value.filter(course => course.inscription.pourcentageProgression > 0 && course.inscription.pourcentageProgression < 100).length;
  const completed = enrolledCourses.value.filter(course => course.inscription.pourcentageProgression === 100).length;
  return [{ label: 'YOUR COURSES', value: total, detail: 'learning paths' }, { label: 'IN PROGRESS', value: inProgress, detail: 'keep the rhythm' }, { label: 'COMPLETED', value: completed, detail: 'skills earned' }];
});
function getCategoryIcon(category) { return ({ 'Développement Web': '⌘', Backend: '▤', 'Base de Données': '◉', 'Data Science': '◌', DevOps: '↗' })[category] || '✳'; }
onMounted(async () => {
  markLoading();
  try {
    const { data } = await api.get('/my-enrollments');
    enrolledCourses.value = (data || []).sort((a, b) => {
      const score = course => course.inscription.pourcentageProgression > 0 && course.inscription.pourcentageProgression < 100 ? 2 : course.inscription.pourcentageProgression === 0 ? 1 : 0;
      return score(b) - score(a);
    });
  } catch (error) { showErrorToast(error, 'Could not load your courses.'); }
  finally { markLoaded(); }
});
</script>

<style scoped>
