; font-size: 11px; }.instructor-avatar { width: 25px; height: 25px; display: grid; place-items: center; border-radius: 50%; background: #e8eee6; color: #57715d; font-size: 10px; }.resume-button { display: inline-flex; gap: 28px; align-items: center; margin-top: 24px; padding: 12px 15px; border-radius: 4px; background: #537a62; color: white; text-decoration: none; font-size: 11px; font-weight: 650; }.resume-button:hover { background: #456c54; }.resume-progress { display: flex; flex-direction: column; justify-content: center; padding: 28px; background: #f4f5ef; }.progress-top { display: flex; justify-content: space-between; align-items: end; }.progress-top > div { display: grid; gap: 8px; }.progress-top strong { font-family: Georgia, serif; font-size: 47px; font-weight: 400; line-height: 1; }.progress-top strong small { color: #5f725f; font-size: 23px; }.progress-note { color: #657066; font-size: 10px; }.progress-track, .other-progress-track { height: 5px; margin: 19px 0 11px; border-radius: 5px; background: #e2e7de; overflow: hidden; }.progress-track span, .other-progress-track span { display: block; height: 100%; border-radius: inherit; background: #729276; }.progress-foot { display: flex; justify-content: space-between; color: #676f67; font-size: 10px; }.section-heading { display: flex; justify-content: space-between; align-items: end; margin: 48px 0 17px; }.section-heading h2 { margin: 8px 0 0; font-family: 'Iowan Old Style', Georgia, serif; font-size: 29px; font-weight: 400; }.section-count { color: #686f67; font-size: 10px; }.other-course-list { border-top: 1px solid #e7e8e1; }.other-course { display: grid; grid-template-columns: 40px 1fr minmax(90px,170px) 28px; align-items: center; gap: 15px; padding: 16px 8px; border-bottom: 1px solid #e7e8e1; }.other-course-mark { display: grid; place-items: center; width: 34px; height: 34px; border-radius: 5px; background: #e8eee6; color: #58715d; font-size: 16px; }.other-course-copy h3 { margin: 4px 0 3px; font-family: 'Iowan Old Style', Georgia, serif; font-weight: 400; font-size: 17px; }.other-progress { color: #686f68; font-size: 9px; }.other-progress-track { height: 4px; margin: 0; }.other-arrow { display: grid; place-items: center; width: 26px; height: 26px; border: 1px solid #e4e8df; border-radius: 50%; color: #57745c; text-decoration: none; }.dashboard-empty { padding: 54px 22px; text-align: center; border: 1px solid #e5e7df; border-radius: 7px; background: #fff; }.empty-symbol { display: grid; place-items: center; width: 42px; height: 42px; margin: 0 auto 15px; border-radius: 50%; background: #e8eee6; color: #59715e; font-size: 19px; }.dashboard-empty h2 { margin: 10px 0 7px; font-family: 'Iowan Old Style', Georgia, serif; font-size: 31px; font-weight: 400; }.dashboard-empty p { max-width: 430px; margin: 0 auto 20px; color: #686f68; font-size: 12px; line-height: 1.65; }.button-primary { display: inline-flex; gap: 14px; align-items: center; padding: 12px 15px; background: #537a62; color: #fff; text-decoration: none; border-radius: 4px; font-size: 11px; font-weight: 650; }.dashboard-loading { display: grid; gap: 14px; }.skeleton-card { height: 90px; border-radius: 6px; background: linear-gradient(90deg,#f1f2ec,#e8ebe3,#f1f2ec); background-size: 200% 100%; animation: shimmer 1.5s infinite; }.skeleton-card.large { height: 220px; }@keyframes shimmer { to { background-position: -200% 0; } }
@media (max-width: 700px) { .learner-dashboard { padding: 50px 20px 70px; }.dashboard-heading { align-items: flex-start; flex-direction: column; }.stats-row { margin: 25px 0 38px; gap: 7px; }.stat-card { padding: 12px 10px; }.stat-label { font-size: 8px; }.stat-card strong { font-size: 24px; }.stat-detail { font-size: 9px; }.resume-hero-panel { grid-template-columns: 1fr; }.resume-main, .resume-progress { padding: 22px; }.other-course { grid-template-columns: 35px 1fr 25px; gap: 9px; }.other-progress-track { display: none; }.section-heading { margin-top: 36px; } }
@media (prefers-reduced-motion: reduce) { .learner-dashboard *, .learner-dashboard *::before, .learner-dashboard *::after { transition-duration: .01ms !important; animation-duration: .01ms !important; } }
</style>
